// Generate src/api/schema.ts from the backend's JSON Schema (src/api/schema.json).
//
// Refresh both files with `pnpm gen:api`. The backend writes the schema with
// scripts/export_api_schema.py; this script turns every `$defs` entry into an
// exported TypeScript type.
import { readFile, writeFile } from 'node:fs/promises'

import { compile } from 'json-schema-to-typescript'

const SCHEMA = new URL('../src/api/schema.json', import.meta.url)
const OUTPUT = new URL('../src/api/schema.ts', import.meta.url)

const BANNER = `/* eslint-disable */
/**
 * Generated by scripts/gen-api-types.mjs from src/api/schema.json, which the
 * backend exports from its Pydantic models. Do not edit; run \`pnpm gen:api\`.
 */`

/** Keywords whose value maps names (not keywords) to subschemas. */
const NAMED_SUBSCHEMAS = new Set(['$defs', 'properties', 'patternProperties'])

/**
 * Pydantic gives every property schema a `title` keyword.
 * json-schema-to-typescript turns those into named aliases
 * (`type DurationS = number`), so keep the keyword only on definitions.
 * Property *names* such as `title` are kept.
 */
export function stripPropertyTitles(node, isDefinition = false) {
  if (Array.isArray(node)) {
    return node.map((item) => stripPropertyTitles(item))
  }
  if (node === null || typeof node !== 'object') {
    return node
  }
  const out = {}
  for (const [key, value] of Object.entries(node)) {
    if (key === 'title' && !isDefinition) {
      continue
    }
    if (NAMED_SUBSCHEMAS.has(key)) {
      out[key] = Object.fromEntries(
        Object.entries(value).map(([name, sub]) => [
          name,
          stripPropertyTitles(sub, key === '$defs'),
        ]),
      )
      continue
    }
    out[key] = stripPropertyTitles(value)
  }
  return out
}

export async function generate(schema) {
  const root = stripPropertyTitles({
    title: 'ApiSchema',
    type: 'object',
    additionalProperties: false,
    properties: {},
    $defs: schema.$defs,
  })
  const source = await compile(root, 'ApiSchema', {
    bannerComment: BANNER,
    additionalProperties: false,
    unreachableDefinitions: true,
    ignoreMinAndMaxItems: true,
    enableConstEnums: false,
    strictIndexSignatures: true,
    unknownAny: true,
    style: { singleQuote: true, semi: false, printWidth: 100, trailingComma: 'all' },
  })
  // The synthetic root only exists to carry `$defs`.
  return source.replace(/export interface ApiSchema \{\}\n\n?/, '')
}

const isMain = import.meta.url === `file://${process.argv[1]}`
if (isMain) {
  const schema = JSON.parse(await readFile(SCHEMA, 'utf8'))
  await writeFile(OUTPUT, await generate(schema))
  console.log(`Wrote ${OUTPUT.pathname}`)
}
